import json
import math
import sqlite3
from collections import defaultdict
from typing import Any, Dict, List, Tuple

# Optional deps
# pip install pandas pymilvus neo4j sentence-transformers
try:
    import pandas as pd
except Exception:
    pd = None

# Milvus
try:
    from pymilvus import connections, Collection
except Exception:
    connections = None
    Collection = None

# Neo4j
try:
    from neo4j import GraphDatabase
except Exception:
    GraphDatabase = None

# Embedding model
try:
    from sentence_transformers import SentenceTransformer
except Exception:
    SentenceTransformer = None


# -----------------------
# Fixed configuration (as required)
# -----------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# -----------------------
# Helpers
# -----------------------
def safe_json_loads(s: Any) -> Dict[str, Any]:
    if s is None:
        return {}
    if isinstance(s, dict):
        return s
    if not isinstance(s, str):
        return {}
    s = s.strip()
    if not s or s.lower() == 'none':
        return {}
    # Some datasets store JSON with single quotes; try to normalize carefully.
    try:
        return json.loads(s)
    except Exception:
        # fallback: replace single quotes with double quotes (best-effort)
        try:
            s2 = s.replace("'", '"')
            return json.loads(s2)
        except Exception:
            return {}


def normalize_wifi(v: Any) -> str:
    if v is None:
        return "unknown"
    if isinstance(v, str):
        return v.strip().lower().strip('"')
    return str(v).strip().lower()


def truthy(v: Any) -> bool:
    if v is True:
        return True
    if v is False or v is None:
        return False
    if isinstance(v, (int, float)):
        return v != 0
    if isinstance(v, str):
        return v.strip().lower() in {"true", "1", "yes", "y"}
    return False


def connect_sqlite(path: str) -> sqlite3.Connection:
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    return con


def fetch_tucson_coffee_candidates(limit: int = 300) -> List[Dict[str, Any]]:
    con = connect_sqlite(sqlite_paths["business"])
    q = """
    SELECT business_id, name, address, city, state, postal_code,
           stars, review_count, categories, attributes
    FROM business
    WHERE city = ?
      AND (categories LIKE ? OR categories LIKE ?)
    ORDER BY stars DESC, review_count DESC
    LIMIT ?;
    """
    rows = con.execute(q, ("Tucson", "%Coffee%", "%Cafes%", limit)).fetchall()
    con.close()
    out = []
    for r in rows:
        out.append(dict(r))
    return out


def filter_by_attributes(biz: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    out = []
    for b in biz:
        attrs = safe_json_loads(b.get("attributes"))
        wifi = normalize_wifi(attrs.get("WiFi"))
        good_for_working = truthy(attrs.get("GoodForWorking"))

        # Hard filter: WiFi should not be explicitly 'no'
        if wifi == "no":
            continue
        # Keep if wifi is free/paid/unknown, but prefer those with explicit good_for_working
        b["_attrs"] = attrs
        b["wifi"] = wifi
        b["good_for_working"] = good_for_working
        out.append(b)

    # Prefer GoodForWorking==True: keep all, but we will rank it higher
    return out


def keyword_signal_from_sqlite_reviews(biz_ids: List[str], max_snippets_per_biz: int = 2) -> Tuple[Dict[str, Dict[str, Any]], Dict[str, List[str]]]:
    """Fallback when Milvus/embeddings are unavailable.
    Returns counts and snippets per business.
    """
    if not biz_ids:
        return {}, {}

    con = connect_sqlite(sqlite_paths["review"])
    # SQLite parameter limit: chunk to be safe
    chunk_size = 400
    counts = defaultdict(lambda: {"wifi_mentions": 0, "work_mentions": 0, "outlet_mentions": 0})
    snippets = defaultdict(list)

    patterns = {
        "wifi": "%wifi%",
        "laptop": "%laptop%",
        "work": "%work%",
        "study": "%study%",
        "outlet": "%outlet%",
        "plug": "%plug%",
        "socket": "%socket%"
    }

    for i in range(0, len(biz_ids), chunk_size):
        chunk = biz_ids[i:i+chunk_size]
        placeholders = ",".join(["?"] * len(chunk))
        q = f"""
        SELECT business_id, review_id, text
        FROM review
        WHERE business_id IN ({placeholders})
          AND (
                lower(text) LIKE ? OR
                lower(text) LIKE ? OR
                lower(text) LIKE ? OR
                lower(text) LIKE ? OR
                lower(text) LIKE ? OR
                lower(text) LIKE ? OR
                lower(text) LIKE ?
              );
        """
        params = chunk + [
            patterns["wifi"], patterns["laptop"], patterns["work"], patterns["study"],
            patterns["outlet"], patterns["plug"], patterns["socket"]
        ]
        rows = con.execute(q, params).fetchall()
        for r in rows:
            bid = r["business_id"]
            text = (r["text"] or "").strip()
            t = text.lower()
            if "wifi" in t:
                counts[bid]["wifi_mentions"] += 1
            if ("laptop" in t) or ("work" in t) or ("study" in t):
                counts[bid]["work_mentions"] += 1
            if ("outlet" in t) or ("plug" in t) or ("socket" in t):
                counts[bid]["outlet_mentions"] += 1

            if len(snippets[bid]) < max_snippets_per_biz:
                snippets[bid].append(text[:240].replace("\n", " "))

    con.close()
    return dict(counts), dict(snippets)


def milvus_semantic_signal(biz_ids: List[str], query: str, topk: int = 200, max_snippets_per_biz: int = 2):
    """Use Milvus vector search on reviews. Best-effort due to unknown schema.
    Expected fields (common pattern): business_id (string), review_id (string/int), text (string), vector field e.g. 'embedding'/'text_vector'.
    If schema mismatches, this function will raise and caller should fallback.
    """
    if connections is None or Collection is None:
        raise RuntimeError("pymilvus not installed")
    if SentenceTransformer is None:
        raise RuntimeError("sentence-transformers not installed")

    connections.connect(host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])
    col = Collection(milvus_config['milvus_collections']['reviews'])
    col.load()

    model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
    qvec = model.encode([query], normalize_embeddings=True).tolist()

    # Try common vector field names
    vector_fields_to_try = ["text_vector", "embedding", "vector"]
    output_fields = ["business_id", "review_id", "text"]

    counts = defaultdict(lambda: {"semantic_hits": 0, "best_score": None})
    snippets = defaultdict(list)

    # expr: attempt to filter by business_id list (may fail if field not present)
    # Milvus expr string requires quotes around strings.
    biz_ids_escaped = [bid.replace('"', '\\"') for bid in biz_ids]
    expr = None
    if biz_ids_escaped:
        # If business_id is VarChar field this should work
        quoted = ",".join([f'"{b}"' for b in biz_ids_escaped])
        expr = f"business_id in [{quoted}]"

    last_err = None
    for vec_field in vector_fields_to_try:
        try:
            res = col.search(
                data=qvec,
                anns_field=vec_field,
                param={"metric_type": "IP", "params": {"nprobe": 16}},
                limit=topk,
                expr=expr,
                output_fields=output_fields
            )
            # res is a list with one element per query vector
            hits = res[0]
            for h in hits:
                ent = getattr(h, "entity", None)
                if ent is None:
                    continue
                bid = ent.get("business_id") if hasattr(ent, "get") else None
                text = ent.get("text") if hasattr(ent, "get") else None

                if bid is None:
                    continue
                # If expr filtering didn't work, filter here
                if biz_ids and bid not in set(biz_ids):
                    continue

                score = float(getattr(h, "score", 0.0))
                counts[bid]["semantic_hits"] += 1
                if counts[bid]["best_score"] is None or score > counts[bid]["best_score"]:
                    counts[bid]["best_score"] = score

                if text and len(snippets[bid]) < max_snippets_per_biz:
                    snippets[bid].append(str(text)[:240].replace("\n", " "))
            return dict(counts), dict(snippets)
        except Exception as e:
            last_err = e
            continue

    raise RuntimeError(f"Milvus search failed for all candidate vector fields. Last error: {last_err}")


def neo4j_graph_signal(biz_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    if GraphDatabase is None:
        return {}
    if not biz_ids:
        return {}

    driver = None
    try:
        driver = GraphDatabase.driver(neo4j_config['neo4j_uri'], auth=neo4j_config['neo4j_auth'])
        cypher = """
        MATCH (u:User)-[:WROTE]->(:Review)-[:ABOUT]->(b:Business)
        WHERE b.business_id IN $biz_ids
        RETURN b.business_id AS business_id,
               count(DISTINCT u) AS unique_reviewers,
               sum(CASE WHEN coalesce(u.elite,false) = true THEN 1 ELSE 0 END) AS elite_reviewers
        """
        with driver.session() as session:
            rows = session.run(cypher, biz_ids=biz_ids)
            out = {}
            for r in rows:
                out[r["business_id"]] = {
                    "unique_reviewers": int(r["unique_reviewers"] or 0),
                    "elite_reviewers": int(r["elite_reviewers"] or 0)
                }
            return out
    except Exception:
        # Graph is optional; ignore errors
        return {}
    finally:
        if driver is not None:
            driver.close()


def rank_and_print(biz: List[Dict[str, Any]], text_counts: Dict[str, Dict[str, Any]], text_snips: Dict[str, List[str]], graph_counts: Dict[str, Dict[str, Any]], topn: int = 10):
    scored = []
    for b in biz:
        bid = b["business_id"]
        stars = float(b.get("stars") or 0.0)
        rc = int(b.get("review_count") or 0)
        wifi = b.get("wifi", "unknown")
        gfw = 1.0 if b.get("good_for_working") else 0.0

        tc = text_counts.get(bid, {})
        wifi_m = float(tc.get("wifi_mentions", tc.get("semantic_hits", 0)) or 0)
        work_m = float(tc.get("work_mentions", 0) or 0)
        outlet_m = float(tc.get("outlet_mentions", 0) or 0)

        gc = graph_counts.get(bid, {})
        uniq = float(gc.get("unique_reviewers", 0) or 0)
        elite = float(gc.get("elite_reviewers", 0) or 0)

        # Normalize-ish signals
        text_signal = math.log1p(wifi_m + 0.7 * work_m + 0.5 * outlet_m)
        graph_signal = math.log1p(uniq) + 0.3 * math.log1p(elite)

        wifi_bonus = 0.25 if wifi == "free" else (0.10 if wifi == "paid" else 0.0)

        score = (
            0.55 * stars +
            0.18 * math.log1p(rc) +
            0.17 * text_signal +
            0.07 * graph_signal +
            0.03 * gfw +
            wifi_bonus
        )

        scored.append({
            "business_id": bid,
            "name": b.get("name"),
            "address": f"{b.get('address','')}, {b.get('city','')}, {b.get('state','')} {b.get('postal_code','')}",
            "stars": stars,
            "review_count": rc,
            "wifi": wifi,
            "good_for_working": bool(b.get("good_for_working")),
            "text_counts": tc,
            "graph_counts": gc,
            "snippets": text_snips.get(bid, []),
            "score": score
        })

    scored.sort(key=lambda x: x["score"], reverse=True)

    # Print
    print(f"Top {topn} Tucson coffee shops (WiFi + laptop/work friendly signals):\n")
    for i, x in enumerate(scored[:topn], 1):
        print(f"{i}. {x['name']}  | {x['stars']}★ ({x['review_count']} reviews)  | WiFi: {x['wifi']}  | GoodForWorking: {x['good_for_working']}")
        print(f"   {x['address']}")
        if x.get("text_counts"):
            print(f"   Text signal: {x['text_counts']}")
        if x.get("graph_counts"):
            print(f"   Graph signal: {x['graph_counts']}")
        if x.get("snippets"):
            for s in x["snippets"]:
                print(f"   - \"{s}\"")
        print(f"   Score: {x['score']:.3f}\n")

    return scored


def main(topn: int = 10):
    # 1) SQL candidates
    biz = fetch_tucson_coffee_candidates(limit=300)
    if not biz:
        print("No candidates found in business.db for Tucson + Coffee/Cafes.")
        return

    # 2) attribute filter
    biz2 = filter_by_attributes(biz)

    # Further prioritize: keep all, but if too many, downselect to top by stars/review_count for text search cost
    biz2.sort(key=lambda b: (float(b.get('stars') or 0), int(b.get('review_count') or 0)), reverse=True)
    biz2 = biz2[:120]

    biz_ids = [b["business_id"] for b in biz2]

    # 3) Text signal: prefer Milvus semantic; fallback to SQLite keyword
    query = "good wifi laptop friendly place to work or study with outlets"
    text_counts = {}
    text_snips = {}

    try:
        text_counts, text_snips = milvus_semantic_signal(biz_ids, query=query, topk=300, max_snippets_per_biz=2)
        # Map semantic to unified keys
        text_counts = {
            bid: {
                "semantic_hits": v.get("semantic_hits", 0),
                "best_score": v.get("best_score", None)
            } for bid, v in text_counts.items()
        }
    except Exception as e:
        # Fallback
        print(f"[Info] Milvus semantic search unavailable, falling back to SQLite keyword scan. Reason: {e}")
        text_counts, text_snips = keyword_signal_from_sqlite_reviews(biz_ids, max_snippets_per_biz=2)

    # 4) Optional graph signal
    graph_counts = neo4j_graph_signal(biz_ids)

    # 5) Rank + print
    rank_and_print(biz2, text_counts=text_counts, text_snips=text_snips, graph_counts=graph_counts, topn=topn)


if __name__ == "__main__":
    main(topn=10)

